            String value = decode(field.substring(equals + 1));
            if (!key.matches("[a-z0-9-]+")) {
                throw new IllegalArgumentException("invalid key");
            }
            properties.putIfAbsent(key, value);
        }

        StringBuilder result = new StringBuilder();
        for (Map.Entry<String, String> entry : properties.entrySet()) {
            if (result.length() > 0) {
                result.append(';');
            }
            result.append(entry.getKey()).append('=').append(encode(entry.getValue()));
        }
        return result.toString();
    }

    private static String decode(String component) {
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < component.length(); i++) {
            char c = component.charAt(i);
            if (c == '%') {
                if (i + 2 >= component.length()) {
                    throw new IllegalArgumentException("incomplete escape");
                }
                int high = Character.digit(component.charAt(i + 1), 16);
                int low = Character.digit(component.charAt(i + 2), 16);
                if (high < 0 || low < 0) {
                    throw new IllegalArgumentException("invalid escape");
                }
                c = (char) (high * 16 + low);
                i += 2;
            } else if (c < 32 || c > 126 || c == ';' || c == '=') {
                throw new IllegalArgumentException("invalid literal");
            }
            if (c < 32 || c > 126) {
                throw new IllegalArgumentException("decoded character is not printable ASCII");
            }
            result.append(c);
        }
        return result.toString();
    }

    private static String encode(String value) {
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '%' || c == ';' || c == '=') {
